/**
 * The systemd unit that runs a long job and wakes the goal when it exits — **L3** of the wake
 * transport.
 *
 * Why a generated file and not a daemon: the waiting decision forbids a self-written scheduler
 * (rule 10) and forbids a long job living inside the agent's process tree (rule 5). systemd already
 * owns process lifetime and already knows how a process ended; all engram has to do is emit the
 * unit and read the outcome on the way out. That is what makes the 16-hour job survivable: the
 * agent is not the job's parent, so filling a context or closing a pane cannot orphan it.
 *
 * Three properties are load-bearing, and each one is a failure mode seen elsewhere in this codebase:
 *
 * 1. **`ExecStopPost`, not `OnSuccess`.** The wake must fire on *every* exit path — a crash, an OOM
 *    kill, a `systemctl stop`. With `OnSuccess` a failed job would strand the goal silently, which
 *    is precisely the failure the wake exists to prevent. systemd exports `$SERVICE_RESULT`,
 *    `$EXIT_CODE` and `$EXIT_STATUS` to `ExecStopPost`, and `engram goal wake` folds them into the
 *    reason, so the agent judges an exit against `done_when` instead of trusting it.
 * 2. **No shell.** Every argument is its own word, so no quoting rule can turn a goal id or a reason
 *    into a second command.
 * 3. **`%` is a systemd specifier.** A goal text containing a percent sign would be rewritten by
 *    systemd before `engram` ever saw it, so it is escaped rather than passed through.
 *
 * This module builds strings only — no filesystem, like every other `templates/` module.
 */

export interface GoalUnitContext {
  /** Goal id, e.g. `2026-10-18-m3-wake-transports`. It lands in the unit *name*, so it must be a slug. */
  id: string;
  /** The goal's own text, for `Description=`. Folded onto one line and specifier-escaped. */
  goal: string;
  /** Absolute project root. Becomes `WorkingDirectory` so `engram` finds `.ai/` from inside the unit. */
  root: string;
  /**
   * `ExecStart` payload, verbatim.
   *
   * Deliberately not parsed by engram: systemd's own word splitting (and its `$VAR` expansion) is
   * the contract the user already knows, and re-implementing it here would be a second, disagreeing
   * parser.
   */
  job: string;
  /** argv prefix that runs engram — `['/usr/bin/engram']`, or `['node', '/path/build/src/cli.js']`. */
  engram: string[];
  /**
   * The `PATH` baked into the unit.
   *
   * A systemd *user* unit does not inherit a login shell's `PATH`, and `engram` is typically
   * installed outside `/usr/bin` (npm global prefix). Without this the unit starts, the job runs,
   * and the wake resolves to `ENOENT` — an installed goal engine that records nothing.
   */
  path: string;
  /** Base wake reason. The unit's observed result is appended by `engram goal wake` itself. */
  reason?: string;
}

/** `engram-goal-<id>.service` — the name a user types for `systemctl --user start`. */
export const goalUnitName = (id: string): string => `engram-goal-${id}.service`;

/** The header `sync`/`unit` matches before a generated unit may be replaced. */
export const GOAL_UNIT_HEADER = '# generated by engram';

/** Words systemd's `Exec*` parser takes literally; anything else gets quoted. */
const BARE = /^[A-Za-z0-9._/:=@+-]+$/;

/**
 * One `Exec*` word.
 *
 * Quoting is not cosmetic: systemd splits `ExecStart`/`ExecStopPost` on whitespace, so an unquoted
 * project root containing a space would silently become two arguments and the command would see a
 * different path than the one that was printed.
 */
export function systemdWord(word: string): string {
  if (BARE.test(word)) return word;
  return `"${word.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

/** A line value: newlines would end the directive, and `%` is a systemd specifier. */
function unitValue(text: string): string {
  return text.replace(/\s+/g, ' ').trim().replace(/%/g, '%%');
}

/**
 * The parts of a systemd unit's exit report that say how the job ended.
 *
 * Read from the environment of an `ExecStopPost` process rather than passed on the command line:
 * systemd sets these variables itself, and a `$SERVICE_RESULT` written into a unit file would be
 * expanded by systemd *before* engram ran — one more quoting rule to get wrong for no gain.
 *
 * The distinction matters to the reader: `result=success status=0` and `result=exit-code status=137`
 * (SIGKILL, usually the OOM killer) are both "the process ended", and only one of them is good news.
 */
export function unitOutcome(env: NodeJS.ProcessEnv): string | null {
  const result = env.SERVICE_RESULT?.trim();
  const code = env.EXIT_CODE?.trim();
  const status = env.EXIT_STATUS?.trim();
  if (!result && !code && !status) return null;
  const parts: string[] = [];
  if (result) parts.push(`result=${result}`);
  if (code) parts.push(`code=${code}`);
  if (status) parts.push(`status=${status}`);
  return `unit ${parts.join(' ')}`;
}

export function goalUnitSource(ctx: GoalUnitContext): string {
  const exec = ctx.engram.map(systemdWord).join(' ');
  const reason = systemdWord(ctx.reason ?? `goal unit ${ctx.id} exited`);
  return `${GOAL_UNIT_HEADER} — regenerate with \`engram goal unit ${ctx.id} --job "…"\`; do not hand-edit.
#
# The long job runs here, not inside the agent's process tree: closing the pane, compacting a
# context or restarting pi cannot orphan it. ExecStopPost — not OnSuccess — is what makes a failed
# job reach the goal too, since a process exiting is not the same as a process succeeding. engram
# appends the unit's own $SERVICE_RESULT / $EXIT_STATUS to the wake reason.
[Unit]
Description=${unitValue(`engram goal ${ctx.id}: ${ctx.goal}`)}

[Service]
Type=simple
WorkingDirectory=${systemdWord(ctx.root)}
Environment=PATH=${systemdWord(ctx.path)}
ExecStart=${ctx.job}
ExecStopPost=${exec} goal wake --id ${systemdWord(ctx.id)} --deliver --reason ${reason}
Restart=no

[Install]
WantedBy=default.target
`;
}

/**
 * The argv prefix that runs engram from inside a unit.
 *
 * `tsc` emits `build/src/cli.js` as `0644`, so a development checkout cannot be executed directly —
 * `spawn` fails with `EACCES` and the wake "does nothing" while every log line looks fine. An
 * installed CLI (npm's bin shim) is executable and is used as-is. The absolute path is used in both
 * cases, because a unit does not have the shell's `PATH`.
 */
export function engramCommand(bin: string, isExecutable: boolean, node: string): string[] {
  return isExecutable ? [bin] : [node, bin];
}
